type LessonSeed = {
  id: string;
  title: string;
  minutes: number;
  mechanism: string;
  integration: string;
  clinical: string;
  cues: string[];
  sequence: string[];
  safety: string[];
  example: { context: string; action: string; outcome: string };
  activity: string;
  check: { question: string; options: string[]; answerIndex: number; rationale: string };
};

const lesson = (seed: LessonSeed): Lesson => ({
  id: seed.id,
  title: seed.title,
  durationMinutes: seed.minutes,
  sections: [
    { heading: 'Structure and mechanism', content: seed.mechanism },
    { heading: 'Physiologic integration', content: seed.integration },
    { heading: 'Clinical translation', content: seed.clinical },
  ],
  bedsideCues: seed.cues,
  assessmentSequence: seed.sequence,
  safetyPoints: seed.safety,
  workedExample: seed.example,
  activity: { prompt: seed.activity, type: 'interpretation' },
  knowledgeCheck: seed.check,
});

